def transform(grid):
    # Turn the two interlocking diagonal arms into complete alternating diagonal rays.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # The two color-0 cells indicate diagonal direction; extend the zigzag motif upward.
    # Copy the existing adjacent 2/0/2/0 pattern diagonally toward the top-left.
    for r in range(h-1, -1, -1):
        for c in range(w):
            if out[r][c] == 0:
                # mirror/continue the alternating pattern above-left and above-right
                if r > 0 and c > 0 and out[r-1][c-1] == 5:
                    out[r-1][c-1] = 2
                if r > 0 and c+1 < w and out[r-1][c+1] == 5:
                    out[r-1][c+1] = 2
    return out
