            "content": "def transform(grid):\n    # The pattern is an alternating two-color diagonal cluster; extend existing\n    # 2 cells one row upward along both diagonals, continuing the triangular motif.\n    out = [row[:] for row in grid]\n    h, w = len(out), len(out[0])\n    for r in range(h - 1, 0, -1):\n        for c in range(w):\n            if out[r][c] == 2:\n                for nc in (c - 1, c + 1):\n                    if 0 <= nc < w and out[r - 1][nc] == 5:\n                        out[r - 1][nc] = 2\n    return out\n"
          }
