{
 "path": "programs/task-44ca7449.py",
 "content": "def transform(grid):
    # Complete the 2-colored diagonal shape by extending the marked diagonal edge.
    # Every occupied cell contributes diagonal 2s in both directions; keep the two 0 markers.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # The 2s form a short staircase; fill outward diagonally from that staircase,
    # but only inside its 3x3 neighborhood.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5 and r >= h - 3 and 5 <= c <= 9:
                # Input's two diagonal strokes define the local alternating pattern.
                if (r + c) % 2 == 1:
                    out[r][c] = 2
    return out
"
}

