{
 "path": "programs/task-44ca7449.py",
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Extend each diagonal streak from its upper endpoint, following its slope.
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] in (0, 2)]
    for color in (0, 2):
        cells = [(r, c) for r, c in pts if grid[r][c] == color]
        if len(cells) < 2:
            continue
        # recognize the diagonal direction and take the endpoint with smallest row
        pairs = []
        for r, c in cells:
            for rr, cc in cells:
                if rr > r and abs(cc-c) == rr-r:
                    dc = 1 if cc > c else -1
                    pairs.append((r, c, rr, cc, dc))
        if not pairs:
            continue
        r, c, rr, cc, dc = min(pairs, key=lambda p: (p[0], p[1]))
        # Continue from the upper endpoint away from the rest of the segment.
        dr, stepc = -1, -dc
        while 0 <= r+dr < h and 0 <= c+stepc < w:
            r += dr; c += stepc
            if out[r][c] == 5:
                out[r][c] = color
    return out
"
}

