 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Continue the diagonal tracks from their exposed upper ends, away from the
    # existing pattern. 0s slope down-right; 2s slope down-left in this input.
    for color, dc in ((0, -1), (2, 1)):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(cells) < 2:
            continue
        # Upper endpoint of matching diagonal line; extend one step upward
        # and opposite in column from the line's downward direction.
        candidates = []
        for r, c in cells:
            if (r + 1, c - dc) in cells:
                candidates.append((r, c))
        if not candidates:
            continue
        r, c = min(candidates)
        r -= 1
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] == 5:
                out[r][c] = color
            r -= 1
            c += dc
    return out
