 "path": "programs/task-44ca7449.py",
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Extend each contiguous diagonal stroke away from its upper end.
    for color, dc in ((0, 1), (2, -1)):
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        starts = [(r, c) for r, c in pts if (r + 1, c + dc) in pts]
        if starts:
            r, c = min(starts)
            r -= 1
            c -= dc
            while 0 <= r < h and 0 <= c < w:
                if out[r][c] == 5:
                    out[r][c] = color
                r -= 1
                c -= dc
    return out
"
