{
 "path": "programs/task-44ca7449.py",
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Demonstrations show an existing diagonal line of 9s extended backward
    # (up-left) to the grid boundary. Preserve original cells and extend only
    # from the run's upper endpoint. Generalize using the non-background motif.
    color_counts = {}
    for row in grid:
        for v in row:
            color_counts[v] = color_counts.get(v, 0) + 1
    background = max(color_counts, key=color_counts.get)
    for color in color_counts:
        if color == background:
            continue
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for dr, dc in ((1, 1), (1, -1)):
            starts = [(r, c) for r, c in pts if (r + dr, c + dc) in pts]
            if starts:
                r, c = min(starts)
                rr, cc = r - dr, c - dc
                while 0 <= rr < h and 0 <= cc < w:
                    if out[rr][cc] == background:
                        out[rr][cc] = color
                    rr -= dr
                    cc -= dc
    return out
"
}

{
 "path": "programs/task-44ca7449.py",
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Continue each diagonal run away from the existing run, as illustrated by
    # the examples' parallel colored diagonal rays.
    for color in set(v for row in grid for v in row):
        if color == 5:
            continue
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(cells) < 2:
            continue
        # Find the diagonal pair and its direction from upper to lower endpoint.
        pair = None
        for r, c in cells:
            for rr, cc in cells:
                if rr > r and abs(cc-c) == rr-r:
                    pair = (r, c, 1, 1 if cc > c else -1)
                    break
            if pair:
                break
        if not pair:
            continue
        r, c, dr, dc = pair
        # Extend from the upper endpoint in the opposite direction.
        r -= dr
        c -= dc
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] == 5:
                out[r][c] = color
            r -= dr
            c -= dc
    return out
"
